
import { createClient } from '@/lib/supabase/server';
import { notFound, redirect } from 'next/navigation';
import ReadMoreOrLoginClient from '@/components/letters/ReadMoreOrLoginClient';
import { parseRichTextContent } from '@/lib/contentParser';
import { sanitizeMetadata } from '@/lib/metadataSanitize';

const SITE = 'https://www.merkurov.love';

type PageProps = {
  params: { slug: string } | Promise<{ slug: string }>;
};

function getIssueBody(html: string): string | null {
  // The HTML is generated by our own issue renderer and stored as a snapshot.
  const match = html.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
  return match?.[1] ?? null;
}

function getIssueStyles(html: string): string {
  const match = html.match(/<style\b[^>]*>([\s\S]*?)<\/style>/i);
  return match?.[1] ?? '';
}

export async function generateMetadata({ params }: PageProps) {
  const { slug } = await params;

  try {
    const supabase = createClient({ useServiceRole: true });

    const { data: issue } = await supabase
      .from('letters')
      .select('title,slug,kind,status,published,html_web,payload,content')
      .eq('slug', slug)
      .eq('published', true)
      .maybeSingle();

    if (issue?.kind === 'issue' && issue.status === 'published') {
      const title = issue.title || 'Flow | Anton Merkurov';
      const lang = issue.payload?.lang === 'ru' ? 'ru' : 'en';
      const period = issue.payload?.period;
      const description = period
        ? lang === 'ru'
          ? `Выпуск Flow за период ${new Date(period.start).toLocaleDateString('ru-RU', { timeZone: 'UTC' })} — ${new Date(period.end).toLocaleDateString('ru-RU', { timeZone: 'UTC' })}.`
          : `Flow issue, ${new Date(period.start).toLocaleDateString('en-GB', { timeZone: 'UTC' })} — ${new Date(period.end).toLocaleDateString('en-GB', { timeZone: 'UTC' })}.`
        : 'Flow newspaper issue.';

      return sanitizeMetadata({
        title,
        description,
        alternates: { canonical: `${SITE}/letters/${encodeURIComponent(slug)}` },
        openGraph: {
          title,
          description,
          url: `${SITE}/letters/${slug}`,
          images: [`${SITE}/default-og.png`],
          type: 'article',
        },
        twitter: {
          card: 'summary_large_image',
          title,
          description,
          images: [`${SITE}/default-og.png`],
        },
      });
    }

    const { data: letter, error } = await supabase
      .from('letters')
      .select('title,content')
      .eq('slug', slug)
      .eq('published', true)
      .maybeSingle();

    if (error || !letter) {
      return sanitizeMetadata({ title: 'Letter | Anton Merkurov' });
    }

    const title = letter.title || 'Letter';
    const description = String(
      parseRichTextContent(letter.content || ''),
    ).slice(0, 160);

    return sanitizeMetadata({
      title,
      description,
      openGraph: {
        title,
        description,
        url: `${SITE}/letters/${slug}`,
        images: [`${SITE}/default-og.png`],
        type: 'article',
      },
      alternates: {
        canonical: `${SITE}/letters/${encodeURIComponent(slug)}`,
      },
      twitter: {
        card: 'summary_large_image',
        title,
        description,
        images: [`${SITE}/default-og.png`],
      },
    });
  } catch {
    return sanitizeMetadata({ title: 'Letter | Anton Merkurov' });
  }
}

export default async function LetterPage({ params }: PageProps) {
  const { slug } = await params;

  // Check for a published Flow issue before applying ordinary-letter auth rules.
  const supabasePublic = createClient({ useServiceRole: true });

  const { data: issue, error: issueError } = await supabasePublic
    .from('letters')
    .select(
      'id,title,slug,kind,status,published,html_web,payload,publishedAt,createdAt',
    )
    .eq('slug', slug)
    .eq('kind', 'issue')
    .eq('status', 'published')
    .eq('published', true)
    .maybeSingle();

  if (issueError) {
    console.error('[Flow issue] Failed to load issue:', issueError);
  }

  if (issue) {
    const html = String(issue.html_web || '');
    const body = getIssueBody(html);
    const styles = getIssueStyles(html);

    if (!body) {
      console.error(`[Flow issue] Published issue ${slug} has no HTML body`);
      notFound();
    }

    const issueDate = issue.publishedAt || issue.createdAt || undefined;
    const lang = issue.payload?.lang === 'ru' ? 'ru' : 'en';
    const period = issue.payload?.period;

    const articleSchema = {
      '@context': 'https://schema.org',
      '@type': 'NewsArticle',
      headline: issue.title || 'Flow',
      datePublished: issueDate,
      inLanguage: lang,
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': `${SITE}/letters/${slug}`,
      },
      author: {
        '@type': 'Person',
        name: 'Anton Merkurov',
        url: SITE,
      },
      publisher: {
        '@type': 'Person',
        name: 'Anton Merkurov',
        url: SITE,
      },
      ...(period
        ? {
            temporalCoverage: `${period.start}/${period.end}`,
          }
        : {}),
    };

    return (
      <main
        lang={lang}
        className="min-h-screen bg-white text-[#1C1A1B]"
      >
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(articleSchema).replace(/</g, '\\u003c'),
          }}
        />
        <style>{styles}</style>
        <div dangerouslySetInnerHTML={{ __html: body }} />
      </main>
    );
  }

  // Original behaviour for ordinary letters remains unchanged.
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (user) {
    redirect(`/letters/${slug}/full`);
  }

  const { data: letter, error } = await supabasePublic
    .from('letters')
    .select(
      'id,title,slug,content,published,publishedAt,createdAt,authorId,users(name)',
    )
    .eq('slug', slug)
    .eq('published', true)
    .maybeSingle();

  if (error || !letter) {
    notFound();
  }

  const letterAuthor = Array.isArray(letter.users)
    ? letter.users[0]
    : letter.users;

  const plainContent = parseRichTextContent(letter.content || '');
  const previewContent = plainContent.slice(0, 300);
  const hasMore = plainContent.length > 300;

  const datePublished = letter.publishedAt || letter.createdAt;

  const breadcrumbSchema = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      {
        '@type': 'ListItem',
        position: 1,
        name: 'Home',
        item: SITE,
      },
      {
        '@type': 'ListItem',
        position: 2,
        name: 'Letters',
        item: `${SITE}/letters`,
      },
      {
        '@type': 'ListItem',
        position: 3,
        name: letter.title,
        item: `${SITE}/letters/${slug}`,
      },
    ],
  };

  const letterArticleSchema = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: letter.title,
    description: previewContent,
    datePublished: datePublished,
    author: {
      '@type': 'Person',
      name: letterAuthor?.name || 'Anton Merkurov',
      url: SITE,
    },
    publisher: {
      '@type': 'Person',
      name: 'Anton Merkurov',
      url: SITE,
    },
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': `${SITE}/letters/${slug}`,
    },
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(letterArticleSchema).replace(/</g, '\\u003c'),
        }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(breadcrumbSchema).replace(/</g, '\\u003c'),
        }}
      />

      <div className="min-h-screen bg-gradient-to-b from-blue-50 to-white">
        <div className="mx-auto max-w-3xl px-4 py-12">
          <article className="rounded-2xl border border-blue-100 bg-white p-8 shadow-sm">
            <header className="mb-8">
              <h1 className="mb-3 text-3xl font-bold text-gray-900">
                {letter.title}
              </h1>

              <div className="flex items-center gap-4 text-sm text-gray-500">
                <span>{letterAuthor?.name || 'Author'}</span>
                <span>•</span>
                <time dateTime={datePublished}>
                  {datePublished
                    ? new Date(datePublished).toLocaleDateString('en-US', {
                        year: 'numeric',
                        month: 'long',
                        day: 'numeric',
                      })
                    : ''}
                </time>
              </div>
            </header>

            <div className="prose prose-lg max-w-none">
              <div className="leading-relaxed text-gray-700">
                {previewContent}
                {hasMore && '...'}
              </div>
            </div>

            {hasMore && (
              <div className="mt-8 border-t border-gray-200 pt-8">
                <ReadMoreOrLoginClient />
              </div>
            )}
          </article>
        </div>
      </div>
    </>
  );
}
